import{_ as r,o as a,c as o,a2 as s}from"./chunks/framework.BXzK3EA4.js";const e="/assets/%E6%96%B0%E6%89%8B%E6%8C%87%E5%8D%97-%E4%BF%AE%E6%94%B9%E5%AF%86%E7%A0%81.BLT3fNvb.png",n="/assets/%E4%BF%AE%E6%94%B9%E5%AF%86%E7%A0%81%E9%A1%B5%E9%9D%A2.D5V45MeI.png",p="/assets/%E6%96%B0%E6%89%8B%E6%8C%87%E5%8D%97-%E5%AE%89%E5%85%A8%E8%AE%BE%E7%BD%AE.q4Bpyjpy.png",i="/assets/%E5%BC%80%E5%90%AF%E4%B8%A4%E6%AD%A5%E9%AA%8C%E8%AF%81.B4NnaiR_.png",l="/assets/%E5%BC%80%E5%A7%8B%E5%90%AF%E7%94%A8%E4%B8%A4%E6%AD%A5%E9%AA%8C%E8%AF%81.pOhGw648.png",g="/assets/%E8%BE%93%E5%85%A5%E9%AA%8C%E8%AF%81%E7%A0%81.CJa9mRx0.png",c="/assets/%E4%B8%A4%E6%AD%A5%E9%AA%8C%E8%AF%81%E8%AE%BE%E7%BD%AE%E6%88%90%E5%8A%9F11.Cmykw9e_.png",b=JSON.parse('{"title":"账号安全设置","description":"","frontmatter":{"title":"账号安全设置"},"headers":[],"relativePath":"beginners-guide/account/security.md","filePath":"beginners-guide/account/security.md","lastUpdated":1794292918000}'),E={name:"beginners-guide/account/security.md"};function A(h,t,m,u,_,d){return a(),o("div",null,[...t[0]||(t[0]=[s('<p>为保护您的 RakSmart 账号安全，建议至少完成一项安全设置：</p><ul><li>设置复杂度高的登录密码并定期修改。</li><li>开启两步认证。两步认证是登录密码之外的第二层安全保护，也是简单有效的安全防护措施。开启两步认证后，再次登录 RakSmart 时，除输入登录密码外，系统还会提示您输入验证设备生成的校验码。</li></ul><hr><h3 id="修改登录密码" tabindex="-1">修改登录密码 <a class="header-anchor" href="#修改登录密码" aria-label="Permalink to &quot;修改登录密码&quot;">​</a></h3><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在控制台右上角个人头像下拉列表中，单击<strong>修改密码</strong>，进入<strong>修改密码</strong>页面。</p><p><img src="'+e+'" alt="新手指南-修改密码.png"></p></li><li><p>在<strong>修改密码</strong>页面，根据提示和要求修改您的登录密码。也可点击<strong>生成密码</strong>按钮，系统将自动生成一个高强度密码供您使用。</p><p><img src="'+n+'" alt="修改密码页面.png"></p><blockquote><p><strong>重要</strong></p><p>为确保密码安全性，平台建议设置高强度密码。建议：同时使用大小写字符、至少使用一个符号，如 #、$、!、%、&amp; 等，不要使用连续字符。</p></blockquote></li><li><p>在<strong>确认新密码</strong>输入框中再次填写新设置的密码，以确保两次输入的密码一致，避免因输入错误导致密码设置失败。</p></li><li><p>单击<strong>保存修改</strong>。</p></li></ol><hr><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li><p>密码安全性：请务必设置符合平台要求的高强度密码，避免使用过于简单或容易被猜测的密码，如生日、连续数字等，以保障账户安全。</p></li><li><p>密码一致性：在输入新密码和确认新密码时，请注意仔细核对，确保两次输入完全一致，以免因密码不一致导致修改失败。</p></li><li><p>密码保管：新密码设置完成后，请妥善保管，勿向他人泄露。平台将采取安全技术措施保障用户账户安全，但用户自身也需提高安全意识，防止密码被盗用。</p></li><li><p>定期修改：为进一步提升账户安全性，建议用户定期修改密码，如每 3 个月或 6 个月更换一次，降低密码被破解的风险。</p></li></ul><hr><h3 id="开启两步验证" tabindex="-1">开启两步验证 <a class="header-anchor" href="#开启两步验证" aria-label="Permalink to &quot;开启两步验证&quot;">​</a></h3><p>两步验证为用户登录提供了额外的一层保护。一旦启用并配置该功能，每次用户登录时，除了需要输入用户名和密码外，还需提供两步验证代码，如安全码、时间令牌，或从 Google Authenticator、Duo 等专门的身份验证应用程序获取的动态代码。通过这种双重验证方式，极大地增加了账户被非法入侵的难度，显著提升账户安全性。</p><h4 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h4><p>操作前，请在移动设备端下载并安装 Google Authenticator 或 Duo 等应用程序。</p><h4 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h4><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">raksmart 控制台</a>。</p></li><li><p>在控制台右上角个人头像在下拉列表中，单击<strong>安全设置</strong>，进入<strong>安全设置</strong>页面。</p><p><img src="'+p+'" alt="新手指南-安全设置.png"></p></li><li><p>在<strong>安全设置</strong>页面<strong>两步验证</strong>配置框中，单击<strong>点击这里启用</strong>。</p><p><img src="'+i+'" alt="开启两步验证.png"></p><blockquote><p><strong>说明</strong></p><p>若您之前没有设置两步验证，两步验证的状态显示<strong>已禁用</strong>。</p></blockquote></li><li><p>在<strong>启用两步验证</strong>确认页面，单击<strong>开始</strong>。</p><p><img src="'+l+'" alt="开始启用两步验证.png"></p></li><li><p>移动端登录 Google Authenticator，会显示当前 RakSmart 账号的 6 位校验码。</p><blockquote><p><strong>说明</strong></p><p>校验码每 30 秒更新一次。</p></blockquote></li><li><p>在绑定二次验证口令页面，输入上述校验码后单击<strong>提交</strong>。</p><p><img src="'+g+'" alt="输入验证码.png"></p></li><li><p>若身份验证页面提示“绑定成功”，则说明两步验证已成功开启。</p><p><img src="'+c+'" alt="两步验证设置成功11.png"></p></li></ol>',15)])])}const k=r(E,[["render",A]]);export{b as __pageData,k as default};
